void win32_key_gui_msg_cb(void *p)
{

    extern gui_error_t gui_xml_dom_write_key_array(int id, bool up, bool down);
    gui_msg_t *msg = p;

    gui_xml_dom_write_key_array((int)(size_t)msg->payload, 1, 0);
    gui_log("key %d\n", (int)(size_t)msg->payload);

    switch ((int)(size_t)msg->payload)
    {
    case 13:
        /* PC KEY Enter */
        {
            rvd_click_button();
        }
        break;
    case 1073741905:
        /* PC KEY Down */
        {
            rvd_hover_down_button();
        }
        break;
    case 1073741906:
        /* PC KEY Up */
        {
            rvd_hover_up_button();
        }
        break;
    case 27:
        /* PC KEY ESC */
        {
            rvd_click_back();
        }
        break;
    case /*PC KEY LEFT */ 1073741904:
        {
            rvd_hover_left();
        }
        break;
    case /*PC KEY RIGHT */ 1073741903:
        {
            rvd_hover_right();
        }
        break;
    case /*key PageUp up */ 1073741899:
        {

            extern void rvd_tab_last(void);
            // rvd_tab_last();
            void rvd_tab_left(void);
            rvd_tab_left();
        }
        break;
    case /*key PageDown up */ 1073741902:
        {
            extern void rvd_tab_next(void);
            //rvd_tab_next();
            rvd_tab_right();
        }
        break;
    case 1073741898:
        /* PC KEY Home */
        {

            rvd_tab_first();
        }
        break;

    case /*PC KEY R */ 114:
        {
            rvd_update();

            break;

        }
    case /*PC KEY t */ 116:
        {
#if defined APP_C3
            update_page_decrease();
#endif
            break;

        }
    case /*PC KEY O */ 111:
        {
            // gui_app_switch(get_app_xml(), GUI_APP_HANDLE(APP_OTA));
            rvd_switch_to_OTA_screen();
            break;

        }
    case /*PC KEY U */ 117:
        {
            ota_triggered = true;

            break;

        }

        break;
    default:
        break;
    }
}
#endif
